result = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=100.0 * COUNT(transactions_made.WHERE(status == 'success')) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

result = Customers.WHERE(
    (join_date >= "2023-01-01") & 
    (status == "active")
).PARTITION(
    name="countries", 
    by=country
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)
